{
  "decisions": [
    {
      "decision": "machine_assignment_of_operations",
      "evidence": "Operations are assigned to machines, and each machine can process only one operation at a time. ... Operations assigned to the same machine cannot overlap in time.",
      "options": [
        "op 0 of every job on machine 0, op 1 of every job on machine 1 (2-machine flow shop)",
        "each job's two operations on distinct machines with a job-specific assignment (job shop)",
        "all operations on a single machine"
      ],
      "plausibility": [
        0.6,
        0.3,
        0.1
      ],
      "majority_option": "op 0 of every job on machine 0, op 1 of every job on machine 1 (2-machine flow shop)"
    },
    {
      "decision": "domain_of_start_times",
      "evidence": "All start times must be non-negative",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "domain_of_makespan",
      "evidence": "The makespan must be at least as large as the completion time of every operation.",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "makespan_lower_bound_direction",
      "evidence": "The makespan must be at least as large as the completion time of every operation. For example, the makespan must be at least 1 unit of time after the start of Operation 0 of Job 0",
      "options": [
        "makespan >= start + processing_time (>=)",
        "makespan >= start (completion only, no processing time)",
        "makespan >= start + processing_time with strict >"
      ],
      "plausibility": [
        0.9,
        0.05,
        0.05
      ],
      "majority_option": "makespan >= start + processing_time (>=)"
    },
    {
      "decision": "precedence_constraint_direction",
      "evidence": "the second operation cannot start until the first operation has been completed. For example, Operation 1 of Job 0 must start at least 1 unit of time after Operation 0 of Job 0 starts.",
      "options": [
        "start[j,1] >= start[j,0] + processing_time",
        "start[j,1] >= start[j,0] (no processing time gap)",
        "start[j,1] > start[j,0] + processing_time (strict)"
      ],
      "plausibility": [
        0.9,
        0.05,
        0.05
      ],
      "majority_option": "start[j,1] >= start[j,0] + processing_time"
    },
    {
      "decision": "objective_definition",
      "evidence": "The goal is to minimize the total completion time (makespan) of all jobs ... The objective is to minimize the makespan",
      "options": [
        "minimize makespan variable (max completion time)",
        "minimize sum of all operation completion times"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "minimize makespan variable (max completion time)"
    }
  ]
}
